// Generated by supie __VERSION__. Loads Pyodide __RUNTIME_VERSION__ from the
// memory snapshot built by `supie build`.

// Must run before Pyodide is evaluated.
import "./compat.ts";
// Static import so the bundler sees the Emscripten module. Pyodide would
// otherwise import it from a computed path, which bundlers can't follow.
import createPyodideModule from "./runtime/pyodide.asm.mjs";
import { loadPyodide } from "./runtime/pyodide.mjs";

const dirname = (path: string) => path.slice(0, path.lastIndexOf("/")) || "/";

async function readSnapshot(path: string): Promise<Uint8Array> {
  // Bundled static files can be read whole but not opened as streams.
  const stream = new Blob([await Deno.readFile(path)]).stream()
    .pipeThrough(new DecompressionStream("gzip"));
  return new Uint8Array(await new Response(stream).arrayBuffer());
}

export async function loadPython(here: string) {
  const indexURL = `${here}runtime/`;
  const py = await loadPyodide({
    indexURL,
    createPyodideModule,
    lockFileContents: await Deno.readTextFile(`${indexURL}pyodide-lock.json`),
    stdout: (line: string) => console.log(line),
    stderr: (line: string) => console.error(line),
    _loadSnapshot: readSnapshot(`${here}snapshot.bin.gz`),
  });
  // Packages from requirements.txt: unpacked on every boot, since a snapshot
  // can't hold compiled extensions.
  const packages = await Deno.readFile(`${here}packages.zip`).catch(() => null);
  if (packages) {
    const sitePackages = py.runPython("import site; site.getsitepackages()[0]");
    py.unpackArchive(packages, "zip", { extractDir: sitePackages });
  }
  return {
    runtime: "pyodide",
    registerJsModule: (name: string, module: object) => py.registerJsModule(name, module),
    writeFile(path: string, data: string | Uint8Array) {
      py.FS.mkdirTree(dirname(path));
      py.FS.writeFile(path, data);
    },
    run: (code: string) => py.runPython(code),
    get: (name: string) => py.globals.get(name),
  };
}
